insert into card_library (name, kind, tier, cost, effect, rules, flavor, review) values
('Gimme', 'Instant', 'common', 1, 'custom', 'Your golfer''s round 1 score improves by 1 stroke.', 'Inside the leather. Just pick it up.', true),
