('Practice Swing', 'Enchantment', 'common', 0, 'custom', 'Your next booster pack contains one extra Common.', 'Looked great. The real one didn''t.', true),
('Shank', 'Curse', 'common', 1, 'custom', 'Choose an opponent. If their golfer makes a double bogey or worse this tournament, they lose 5%.', 'We don''t say the word.', true),
('Free Relief', 'Instant', 'common', 1, 'custom', 'Cancel one stroke penalty applied to your golfer this tournament.', 'Ground under repair. Allegedly.', true),
('Fore Left!', 'Curse', 'common', 0, 'custom', 'A randomly chosen opponent takes a 2% penalty.', 'Duck.', true),
('Birdie Juice', 'Enchantment', 'common', 1, 'custom', 'Earn $25,000 for every birdie your golfer makes in round 1, up to $200,000.', 'Flask of unknown origin.', true),
('Three-Putt', 'Curse', 'common', 1, 'custom', 'Choose an opponent. Their golfer takes a 1 stroke penalty in round 2.', 'Speed was good.', true),
('Tap-In', 'Enchantment', 'common', 1, 'custom', 'Your golfer''s round 4 score improves by 1 stroke.', 'Never up, never in. This one''s up.', true),
