('Extra Tee', 'Gear', 'common', 0, 'custom', 'You have 4 tees this tournament instead of 3.', 'Found it in the cup holder.', true),
('Breakfast Ball', 'Gear', 'common', 1, 'custom', 'Your first card next tournament costs 1 tee less.', 'Nobody saw the first one.', true),
