('Ham and Egg', 'Enchantment', 'common', 1, 'custom', 'Choose a partner. Whoever''s golfer earns less receives 10% of the other''s prize money.', 'One of us had to show up.', true),
('Fescue', 'Curse', 'common', 1, 'custom', 'Choose an opponent. Their golfer loses 4% for each round over par, up to 12%.', 'Found it. Wish I hadn''t.', true),
('Clubhouse Leader', 'Enchantment', 'common', 1, 'custom', 'Earn $75,000 for each completed round your golfer leads or co-leads.', 'Enjoy it. It''s early.', true),
